<?php require_once __DIR__.'/../inc/functions.php'; require_role(['admin']); $id=intval($_GET['id']); $stmt=$conn->prepare('SELECT * FROM menu WHERE id=?'); $stmt->bind_param('i',$id); $stmt->execute(); $data=$stmt->get_result()->fetch_assoc(); if(!$data){ echo 'Menu tidak ditemukan'; exit; } $errors=[]; if($_SERVER['REQUEST_METHOD']==='POST'){ $kode=$conn->real_escape_string($_POST['kode']); $nama=$conn->real_escape_string($_POST['nama']); $kategori_id = intval($_POST['kategori_id'])?:NULL; $harga=floatval($_POST['harga']); $stok=intval($_POST['stok']); $deskripsi=$conn->real_escape_string($_POST['deskripsi']); $gambar=$data['gambar']; if(isset($_FILES['gambar']) && $_FILES['gambar']['error']===0){ $ext=pathinfo($_FILES['gambar']['name'],PATHINFO_EXTENSION); $allowed=['jpg','jpeg','png','gif']; if(!in_array(strtolower($ext),$allowed)) $errors[]='Format gambar tidak didukung'; else{ $fn=uniqid('menu_').'.'.$ext; $dst=__DIR__.'/../uploads/'.$fn; if(move_uploaded_file($_FILES['gambar']['tmp_name'],$dst)){ if($data['gambar'] && file_exists(__DIR__.'/../'.$data['gambar'])) @unlink(__DIR__.'/../'.$data['gambar']); $gambar='uploads/'.$fn; } } } if(empty($errors)){ $stmt=$conn->prepare('UPDATE menu SET kode=?,nama=?,kategori_id=?,harga=?,stok=?,deskripsi=?,gambar=? WHERE id=?'); $stmt->bind_param('ssiddssi',$kode,$nama,$kategori_id,$harga,$stok,$deskripsi,$gambar,$id); if($stmt->execute()){ flash('msg','Menu diperbarui'); header('Location:/restoran_fix_v2/admin/master_menu.php'); exit; } else $errors[]='Gagal: '.$conn->error; } } $cats=$conn->query('SELECT * FROM kategori'); ?>
<!doctype html><html><head><meta charset="utf-8"><title>Edit Menu</title><link rel="stylesheet" href="/restoran_fix_v2/assets/css/style.css"></head><body><?php include __DIR__.'/../_nav.php'; ?><div class="container card"><h2>Edit Menu</h2><?php if($errors) echo '<div class="alert">'.implode('<br>',$errors).'</div>'; ?><form method="post" enctype="multipart/form-data"><label>Kode</label><input name="kode" value="<?=htmlspecialchars($data['kode'])?>" required><label>Nama</label><input name="nama" value="<?=htmlspecialchars($data['nama'])?>" required><label>Kategori</label><select name="kategori_id"><option value="">-- pilih --</option><?php while($c=$cats->fetch_assoc()): ?><option value="<?=$c['id']?>" <?=($c['id']==$data['kategori_id']?'selected':'')?>><?=htmlspecialchars($c['nama'])?></option><?php endwhile; ?></select><label>Harga</label><input name="harga" type="number" step="100" value="<?=$data['harga']?>" required><label>Stok</label><input name="stok" type="number" value="<?=$data['stok']?>"><label>Deskripsi</label><textarea name="deskripsi"><?=htmlspecialchars($data['deskripsi'])?></textarea><label>Gambar</label><input type="file" name="gambar" accept="image/*"><?php if($data['gambar']): ?><p>Gambar sekarang: <img src="/restoran_fix_v2/<?=htmlspecialchars($data['gambar'])?>" style="max-height:80px"></p><?php endif; ?><button class="btn" type="submit">Update</button></form></div></body></html>